135	// The graph's relations query binds every symbol id TWICE (from_id + to_id). A
136	// large view must NOT exceed SQLITE_MAX_VARIABLE_NUMBER (~32766) — the query is
137	// chunked. With 20k symbols the old single query bound 40001 params and errored,
138	// which silently produced a zero-edge graph that collapses to a dot.
139	func TestFindSemanticRelationsForSymbols_ChunksLargeInClause(t *testing.T) {
140		t.Parallel()
141		dbPath := filepath.Join(t.TempDir(), "semantic.sqlite")
142		db, err := sql.Open(sqlitedriver.Name, dbPath)
143		if err != nil {
144			t.Fatalf("open: %v", err)
145		}
146		if _, err := db.Exec(`CREATE TABLE relations (id INTEGER PRIMARY KEY, from_id TEXT, to_id TEXT, type TEXT, confidence REAL, reason TEXT)`); err != nil {
147			t.Fatalf("create: %v", err)
148		}
149		// rowid 1: sym-1 -> sym-2 ; rowid 2: sym-3 -> sym-1 (both incident to the set)
150		if _, err := db.Exec(`INSERT INTO relations (from_id,to_id,type,confidence,reason) VALUES ('sym-1','sym-2','CALLS',1,''),('sym-3','sym-1','IMPORTS',1,'')`); err != nil {
151			t.Fatalf("insert: %v", err)
152		}
153		db.Close()
154	
155		syms := make([]semanticRecord, 20000) // 40001 bound params unchunked -> would error
156		for i := range syms {
157			syms[i] = semanticRecord{ID: fmt.Sprintf("sym-%d", i+1)}
158		}
159		rels, err := semstore.FindRelationsForSymbolsInSQLite(dbPath, syms, 1000)
160		if err != nil {
161			t.Fatalf("large symbol set errored (chunking regression): %v", err)
162		}
163		if len(rels) != 2 {
164			t.Fatalf("got %d relations, want 2", len(rels))
165		}
166		if rels[0].FromID != "sym-1" || rels[1].FromID != "sym-3" {
167			t.Fatalf("relations not merged in rowid order across chunks: %+v", rels)
168		}
169	}
