22	// writeVizOptimizationStore builds a Graph-owned store fixture (sqlite with the
23	// brain_*_v1 views and entry digest) and returns its live source descriptor,
24	// the only shape the viz read path accepts since the snapshot reader retired.
25	func writeVizOptimizationStore(t *testing.T, brainDir string, records []semanticRecord) *semanticSourceManifest {
26		t.Helper()
27		var body strings.Builder
28		body.WriteString(`{"schema_version":"1.0","provider":"entire-graph","provider_version":"0.1.0","repo_key":"gh/example/repo","commit":"c1","tree":"t1","capabilities":["go"],"warnings":[],"partial_failures":[]}` + "\n")
29		for _, record := range records {
30			line, err := json.Marshal(record)
31			if err != nil {
32				t.Fatal(err)
33			}
34			body.Write(line)
35			body.WriteByte('\n')
36		}
37		repoDir := t.TempDir()
38		ignore, err := loadBrainIgnore(repoDir)
39		if err != nil {
40			t.Fatal(err)
41		}
42		header, counts, filtered, err := filterSemanticSnapshot([]byte(body.String()), ignore, repoDir)
43		if err != nil {
44			t.Fatal(err)
45		}
46		providerDir := t.TempDir()
47		generation, _, err := buildSemanticGeneration(context.Background(), providerDir, repoDir, "viz", bytes.NewReader(filtered), "viz", header, counts, time.Now())
48		if err != nil {
49			t.Fatal(err)
50		}
51		path := filepath.Join(providerDir, generation, semstore.SQLiteName)
52		db, err := sql.Open(sqlitedriver.Name, path)
53		if err != nil {
54			t.Fatal(err)
55		}
56		for _, table := range []string{"symbols", "relations", "files", "reverse_relations", "symbol_fts"} {
57			if _, err = db.Exec("CREATE VIEW brain_" + table + "_v1 AS SELECT * FROM " + table); err != nil {
58				db.Close()
59				t.Fatal(err)
60			}
61		}
62		raw, _ := json.Marshal("viz-fixture")
63		_, err = db.Exec("INSERT INTO meta(key,value) VALUES('entry_digest',?)", string(raw))
64		db.Close()
65		if err != nil {
66			t.Fatal(err)
67		}
68		d := graphStoreDescriptor{ContractVersion: 1, Path: path, EntryDigest: "viz-fixture", Commit: header.Commit, Tree: header.Tree, Header: header, Files: counts.Files, Symbols: counts.Symbols, Relations: counts.Relations}
69		return semstore.GraphStoreSource(d, brainDir)
70	}
