			continue
		}
		if _, excluded := stones.Excluded[id]; !excluded {
			continue
		}
		rel := brainstore.NormalizePrivacyTranscriptPath(session.TranscriptPath)
		if rel != "" {
			out[rel] = id
		}
	}
	return out
}

