import re, glob, sys
root = sys.argv[1]
mods = {
 'bmanifest': 'bmanifest "github.com/entireio/entire-brain/internal/cli/internal/manifest"',
 'historystore': '"github.com/entireio/entire-brain/internal/cli/internal/historystore"',
 'factstore': '"github.com/entireio/entire-brain/internal/cli/internal/factstore"',
 'base': '"github.com/entireio/entire-brain/internal/cli/internal/base"',
 'cmdutil': '"github.com/entireio/entire-brain/internal/cli/internal/cmdutil"',
}
for path in glob.glob(root + '/*.go'):
    with open(path) as f: src = f.read()
    m = re.search(r'import \(\n', src)
    need = []
    for name, imp in mods.items():
        if re.search(r'\b' + name + r'\.', src):
            if name == 'base':
                if '"github.com/entireio/entire-brain/internal/cli/internal/base"' in src:
                    continue
            elif imp.split('"')[1] in src:
                continue
            need.append(imp)
    if not need: continue
    if not m:
        print('NO IMPORT BLOCK:', path); continue
    ins = ''.join('\t' + i + '\n' for i in need)
    src = src[:m.end()] + ins + src[m.end():]
    with open(path, 'w') as f: f.write(src)
    print('imports+', path.rsplit('/',1)[1], [n.rsplit('/',1)[-1].strip('"') for n in need])

